function twoSumOptimal(nums, target) {
  const map = new Map(); // value -> index
  for(let i=0; i<nums.length; i++) {
    const needed = target - nums[i];
    if (map.has(needed)) {
      return [map.get(needed), i];
    }
    map.set(nums[i], i);
  }
  return [];
}
