class TwoSum {
  constructor() { this.map = new Map(); }
  add(number) {
    this.map.set(number, (this.map.get(number) || 0) + 1);
  }
  find(value) {
    for (let [num, count] of this.map) {
      const needed = value - num;
      if (needed === num) {
        if (count > 1) return true;
      } else if (this.map.has(needed)) {
        return true;
      }
    }
    return false;
  }
}
